import{projectRecords,siteRecords,sectionBooks,searchRecords,snippet}from'./search-index.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#e8d19c','#c7d1b5','#dfc5b5'],short=['まにあう','就活手帳','配信','音声','防災','倫理AI','通信','SSL'];
const decorative=i=>`<span class="decorative-spine" style="--book-color:${colors[i%3]};--book-height:${35+i%4*7}px"></span>`;
export function setupSearchShelf(root,projects,initial={}){
 const baseRecords=projectRecords(projects);const motion=matchMedia('(prefers-reduced-motion:reduce)'),section=document.createElement('section');let animations=[],flights=[],matches=[],expanded=false;
 section.className='search-shelf home-section';section.id='search';section.setAttribute('aria-labelledby','search-title');section.innerHTML=`<div class="section-heading"><div><p class="eyebrow">05 / FIND A PROJECT</p><h2 id="search-title" tabindex="-1">本棚からサイト内を探す</h2></div><p>作品・理念・活動・メッセージを、キーワードで探せます。</p></div><form class="shelf-search-form" role="search"><label for="shelf-query">キーワード</label><div class="shelf-search-input"><input id="shelf-query" name="q" type="search" maxlength="100" placeholder="例：音声、使いやすさ、AI" aria-describedby="shelf-search-help" autocomplete="off"><button type="submit">サイト内を探す</button></div><p id="shelf-search-help">スペースで複数の言葉を組み合わせられます。空欄で検索するとすべての本を表示します。</p></form><div class="search-examples"><span>例：</span>${['音声','理念','夢'].map(q=>`<button type="button" data-example="${q}">${q}</button>`).join('')}</div><div class="search-shelf-stage" aria-hidden="true"><div class="shelf-back-row">${sectionBooks.map((s,i)=>`${decorative(i)}<span class="shelf-spine section-spine" data-shelf-kind="${s.id}" style="--book-color:${colors[i%3]};--book-height:48px">${s.short}</span>${decorative(i+1)}`).join('')}</div><div class="shelf-floor"></div><div class="shelf-books">${projects.map((p,i)=>`${decorative(i)}<span class="shelf-spine" data-shelf-kind="${p.kind}" style="--book-color:${colors[i%3]};--book-height:${78+i%3*12}px">${short[i]}</span>${decorative(i+1)}`).join('')}</div></div><p id="shelf-search-status" class="search-status" role="status" aria-live="polite">キーワードを入力して、関連する内容を探せます。</p><ul class="search-results" aria-label="サイト内の検索結果"></ul><div class="search-more"></div>`;root.append(section);
 const input=section.querySelector('input'),list=section.querySelector('.search-results'),status=section.querySelector('.search-status');
 function cancel(){for(const a of animations)a.cancel();animations=[];for(const node of flights)node.remove();flights=[]}
 function presentBooks(){
  cancel();if(motion.matches||document.hidden)return;
  const area=section.getBoundingClientRect(),pairs=[...list.children].slice(0,3).map((el,i)=>{const project=matches[i],spine=section.querySelector(`[data-shelf-kind="${project.id}"]`);return{el:el.querySelector('a'),spine,project,from:spine.getBoundingClientRect(),to:el.getBoundingClientRect()}});
  for(const [i,pair]of pairs.entries()){
   const{from,to,project,spine}=pair,ghost=document.createElement('span'),sx=from.width/60,sy=from.height/80,dx=to.left+to.width/2-from.left-from.width/2,dy=to.top+to.height/2-from.top-from.height/2;
   ghost.className='search-flight';ghost.setAttribute('aria-hidden','true');ghost.style.cssText=`left:${from.left+from.width/2-area.left-30}px;top:${from.top+from.height/2-area.top-40}px;background:${colors[matches.indexOf(project)%3]}`;section.append(ghost);flights.push(ghost);
   const flight=ghost.animate([{transform:`translate(0,0) scale(${sx},${sy})`,opacity:.9},{transform:`translate(${dx*.18}px,-22px) scale(1,1) rotate(-5deg)`,opacity:.8,offset:.28},{transform:`translate(${dx*.8}px,${dy*.8}px) scale(${to.width/60*.8},${to.height/80*.8}) rotate(-2deg)`,opacity:.12,offset:.8},{transform:`translate(${dx}px,${dy}px) scale(${to.width/60},${to.height/80})`,opacity:0}],{duration:650,delay:i*70,easing:'cubic-bezier(.3,.2,.2,1)',fill:'both'});flight.onfinish=()=>ghost.remove();animations.push(flight,spine.animate([{transform:'translateY(0)'},{transform:'translateY(-13px)',offset:.4},{transform:'translateY(0)'}],{duration:500,delay:i*70}));
  }
  for(const [i,el]of[...list.children].entries())animations.push(el.animate([{transform:'translateY(8px)'},{transform:'translateY(0)'}],{duration:230,delay:Math.min(i*30,150),easing:'ease-out'}));
 }
 function paint(){const shown=expanded?matches:matches.slice(0,6);list.innerHTML=shown.map((p,i)=>`<li><a class="search-book" id="search-result-${p.id}" data-route href="${p.path}" style="--book-color:${colors[i%3]}"><span class="search-book-number">${p.number} / ${escape(p.type)}</span><h3>${escape(p.title)}</h3>${p.status?`<span class="lifecycle-badge">${escape(p.status.label)}</span>`:''}<p>${escape(snippet(p,input.value))}</p><span class="search-book-open">詳細を読む ↗</span></a></li>`).join('');section.querySelector('.search-more').innerHTML=matches.length>shown.length?`<button type="button" id="shelf-show-all">残り${matches.length-shown.length}件も表示</button>`:'';section.querySelector('#shelf-show-all')?.addEventListener('click',()=>{expanded=true;section.dataset.expanded='true';paint()})}
 function submit(animate=true){cancel();const records=siteRecords(baseRecords,root);matches=!animate&&initial.resultIds?.length?initial.resultIds.map(id=>records.find(r=>r.id===id)).filter(Boolean):searchRecords(records,input.value);section.dataset.resultIds=JSON.stringify(matches.map(r=>r.id));expanded=Boolean(initial.expanded&&section.dataset.query===undefined);section.dataset.query=input.value;section.dataset.expanded=String(expanded);status.textContent=matches.length?`${matches.length}件が見つかりました。`:'一致する内容はありません。別の言葉で探してみてください。';paint();if(animate&&matches.length)presentBooks()}
 section.querySelector('form').addEventListener('submit',event=>{event.preventDefault();expanded=false;submit()});for(const button of section.querySelectorAll('[data-example]'))button.addEventListener('click',()=>{input.value=button.dataset.example;submit()});if(initial.query!==undefined){input.value=initial.query;submit(false)}
 const hidden=()=>{if(document.hidden)cancel()};motion.addEventListener('change',cancel);window.addEventListener('resize',cancel);document.addEventListener('visibilitychange',hidden);return()=>{cancel();motion.removeEventListener('change',cancel);window.removeEventListener('resize',cancel);document.removeEventListener('visibilitychange',hidden)};
}
